# Terraform Refactor: Duplicated Dev/Prod → Single Module with `for_each`

## Architecture

```
infra/
├── modules/
│   └── app/
│       ├── main.tf
│       ├── variables.tf
│       └── outputs.tf
├── terraform.tf
├── variables.tf
├── main.tf
├── outputs.tf
├── moved.tf
└── environments/
    ├── dev.tfvars
    └── prod.tfvars
```

## `modules/app/variables.tf`

```hcl
variable "name" {
  description = "Environment name (used as prefix for all resources)"
  type        = string
}

variable "region" {
  description = "AWS region"
  type        = string
}

variable "vpc_id" {
  description = "VPC ID to deploy into"
  type        = string
}

variable "subnet_ids" {
  description = "Private subnet IDs for the cluster"
  type        = list(string)
}

# --- EKS ---
variable "eks_cluster_name" {
  type        = string
}

variable "eks_instance_type" {
  type        = string
}

variable "eks_desired_nodes" {
  type        = number
}

# --- S3 ---
variable "s3_bucket_name" {
  type        = string
}

variable "s3_replication_enabled" {
  description = "Enable cross-region replication (prod only)"
  type        = bool
  default     = false
}

variable "s3_replication_target_bucket" {
  description = "Target bucket ARN for CRR"
  type        = string
  default     = ""
}

variable "s3_replication_target_region" {
  type        = string
  default     = "us-west-2"
}

# --- RDS ---
variable "rds_instance_class" {
  type        = string
}

variable "rds_multi_az" {
  type        = bool
}

variable "rds_encrypted" {
  type        = bool
}

variable "rds_db_name" {
  type        = string
  default     = "appdb"
}

variable "rds_db_username" {
  type        = string
  default     = "app"
}

# --- IAM ---
variable "iam_oidc_provider_arn" {
  description = "OIDC provider ARN for IRSA (prod); empty for dev user-based access"
  type        = string
  default     = ""
}

variable "iam_oidc_namespace" {
  type        = string
  default     = "kubernetes.io"
}

variable "iam_oidc_service_account" {
  type        = string
  default     = "default"
}

# --- HTTPS ---
variable "use_cloudfront" {
  description = "Use CloudFront distribution (prod); false uses ALB only (dev)"
  type        = bool
  default     = false
}

variable "acm_certificate_arn" {
  description = "ACM certificate ARN for TLS (required when use_cloudfront=true)"
  type        = string
  default     = ""
}

variable "cloudfront_domain_name" {
  type        = string
  default     = ""
}

# --- Secrets ---
variable "db_password" {
  description = "DB password (pass via SOPS-encrypted var-file, never commit to Git)"
  type        = string
  sensitive   = true
}
```

## `modules/app/main.tf`

```hcl
# =============================================================================
# EKS Cluster
# =============================================================================

resource "aws_eks_cluster" "cluster" {
  name     = var.eks_cluster_name
  role_arn = aws_iam_role.eks_cluster.arn

  vpc_config {
    subnet_ids = var.subnet_ids
  }

  enabled_cluster_log_types = ["api", "audit", "authenticator"]

  tags = {
    Environment = var.name
    ManagedBy   = "terraform"
  }

  depends_on = [aws_iam_role_policy_attachment.eks_cluster]
}

resource "aws_eks_node_group" "workers" {
  cluster_name    = aws_eks_cluster.cluster.name
  node_group_name = "${var.eks_cluster_name}-workers"
  node_role_arn   = aws_iam_role.eks_node.arn
  subnet_ids      = var.subnet_ids

  scaling_config {
    desired_size = var.eks_desired_nodes
    min_size     = var.eks_desired_nodes
    max_size     = var.eks_desired_nodes * 2
  }

  instance_types = [var.eks_instance_type]

  tags = {
    Environment = var.name
  }

  depends_on = [aws_iam_role_policy_attachment.eks_node]
}

# --- EKS IAM ---

resource "aws_iam_role" "eks_cluster" {
  name = "eks-cluster-${var.name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action    = "sts:AssumeRole"
      Effect    = "Allow"
      Principal = { Service = "eks.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster.name
}

resource "aws_iam_role" "eks_node" {
  name = "eks-node-${var.name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action    = "sts:AssumeRole"
      Effect    = "Allow"
      Principal = { Service = "ec2.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy_attachment" "eks_node" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.eks_node.name
}

resource "aws_iam_role_policy_attachment" "eks_node_cni" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  role       = aws_iam_role.eks_node.name
}

# =============================================================================
# S3 Bucket
# =============================================================================

resource "aws_s3_bucket" "assets" {
  bucket = var.s3_bucket_name

  tags = {
    Environment = var.name
  }
}

resource "aws_s3_bucket_versioning" "assets" {
  bucket = aws_s3_bucket.assets.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "assets" {
  bucket = aws_s3_bucket.assets.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "aws:kms"
    }
  }
}

resource "aws_s3_bucket_public_access_block" "assets" {
  bucket = aws_s3_bucket.assets.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Cross-region replication (prod only)
resource "aws_s3_bucket_replication_configuration" "assets" {
  count  = var.s3_replication_enabled ? 1 : 0
  bucket = aws_s3_bucket.assets.id

  role = aws_iam_role.s3_replication.arn

  rules {
    status = "Enabled"
    prefix = "assets/"

    destination {
      bucket        = var.s3_replication_target_bucket
      storage_class = "STANDARD"
    }
  }
}

resource "aws_iam_role" "s3_replication" {
  count = var.s3_replication_enabled ? 1 : 0

  name = "s3-replication-${var.name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action    = "sts:AssumeRole"
      Effect    = "Allow"
      Principal = { Service = "s3.amazonaws.com" }
    }]
  })
}

resource "aws_iam_role_policy" "s3_replication" {
  count  = var.s3_replication_enabled ? 1 : 0
  role   = aws_iam_role.s3_replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "s3:GetReplicationConfiguration",
        "s3:GetBucketVersioning",
        "s3:ReplicateObject",
        "s3:ReplicateDelete",
        "s3:ReplicateTags"
      ]
      Resource = [
        "${aws_s3_bucket.assets.arn}/*",
        "${aws_s3_bucket.assets.arn}"
      ]
    }]
  })
}

# =============================================================================
# RDS PostgreSQL
# =============================================================================

resource "aws_db_subnet_group" "main" {
  name       = "${var.eks_cluster_name}-db"
  subnet_ids = var.subnet_ids

  tags = {
    Environment = var.name
  }
}

resource "aws_security_group" "rds" {
  name   = "${var.eks_cluster_name}-rds"
  vpc_id = var.vpc_id

  ingress {
    description = "PostgreSQL from EKS node group"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"] # restrict to VPC CIDR
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Environment = var.name
  }
}

resource "aws_db_instance" "database" {
  identifier     = "${var.eks_cluster_name}-pg"
  engine         = "postgres"
  engine_version = "15.4"
  instance_class = var.rds_instance_class
  allocated_storage     = 20
  max_allocated_storage = 100
  db_name            = var.rds_db_name
  username           = var.rds_db_username
  password           = var.db_password
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  multi_az               = var.rds_multi_az
  storage_encrypted      = var.rds_encrypted
  storage_type           = "gp3"
  storage_throughput     = 256
  backup_retention_period = 14
  deletion_protection     = true
  publicly_accessible     = false
  skip_final_snapshot     = false
  final_snapshot_identifier = "${var.eks_cluster_name}-pg-final"

  parameters = []

  tags = {
    Environment = var.name
  }
}

# =============================================================================
# IAM Service Account
# =============================================================================

# Dev: IAM user with programmatic access
resource "aws_iam_user" "service" {
  count  = var.iam_oidc_provider_arn == "" ? 1 : 0
  name   = "svc-${var.name}-${var.eks_cluster_name}"
  force_destroy = false

  tags = {
    Environment = var.name
  }
}

resource "aws_iam_access_key" "service" {
  count = var.iam_oidc_provider_arn == "" ? 1 : 0
  user  = aws_iam_user.service[0].name
}

# Prod: OIDC trust role (IRSA)
resource "aws_iam_role" "service_oidc" {
  count = var.iam_oidc_provider_arn != "" ? 1 : 0

  name = "svc-${var.name}-${var.eks_cluster_name}-oidc"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Action = "sts:AssumeRoleWithWebIdentity"
      Effect = "Allow"
      Principal = {
        Federated = var.iam_oidc_provider_arn
      }
      Condition = {
        StringEquals = {
          "${replace(var.iam_oidc_provider_arn, "arn:aws:iam::", "")}:sub" = "system:serviceaccount:${var.iam_oidc_namespace}:${var.iam_oidc_service_account}",
          "${replace(var.iam_oidc_provider_arn, "arn:aws:iam::", "")}:aud" = "sts.amazonaws.com"
        }
      }
    }]
  })

  tags = {
    Environment = var.name
  }
}

# Least-privilege policy for the service account
data "aws_iam_policy_document" "service_policy" {
  statement {
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:ListBucket",
    ]
    resources = [
      aws_s3_bucket.assets.arn,
      "${aws_s3_bucket.assets.arn}/*",
    ]
  }

  statement {
    actions = [
      "rds-db:connect",
    ]
    resources = [
      aws_db_instance.database.arn,
    ]
  }
}

resource "aws_iam_policy" "service" {
  name   = "svc-${var.name}-${var.eks_cluster_name}"
  policy = data.aws_iam_policy_document.service_policy.json
}

resource "aws_iam_user_policy_attachment" "service" {
  count  = var.iam_oidc_provider_arn == "" ? 1 : 0
  user   = aws_iam_user.service[0].name
  policy_arn = aws_iam_policy.service.arn
}

resource "aws_iam_role_policy_attachment" "service_oidc" {
  count      = var.iam_oidc_provider_arn != "" ? 1 : 0
  role       = aws_iam_role.service_oidc[0].name
  policy_arn = aws_iam_policy.service.arn
}

# =============================================================================
# HTTPS (ALB + optional CloudFront)
# =============================================================================

resource "aws_security_group" "alb" {
  name   = "${var.eks_cluster_name}-alb"
  vpc_id = var.vpc_id

  ingress {
    description = "HTTPS"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTP (for health checks)"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/8"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Environment = var.name
  }
}

resource "aws_lb" "main" {
  name               = "${var.eks_cluster_name}-alb"
  load_balancer_type = "application"
  subnets            = var.subnet_ids
  security_groups    = [aws_security_group.alb.id]
  internal           = var.use_cloudfront # CloudFront fronted → internal ALB

  tags = {
    Environment = var.name
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-2016-08"
  certificate_arn   = var.acm_certificate_arn

  default_action {
    type             = "fixed-response"
    fixed_response {
      content_type = "text/plain"
      message_body = "OK"
      status_code  = "200"
    }
  }
}

# CloudFront (prod only)
resource "aws_cloudfront_distribution" "main" {
  count = var.use_cloudfront ? 1 : 0

  enabled             = true
  is_ipv6_enabled     = true
  default_root_object = "index.html"

  origin {
    domain_name              = aws_lb.main.dns_name
    origin_id                = "alb-${var.name}"
    custom_origin_config {
      origin_protocol_policy = "http-only"
      origin_ssl_protocols   = ["TLSv1.2"]
    }
  }

  default_cache_behavior {
    target_origin_id       = "alb-${var.name}"
    viewer_protocol_policy = "redirect-to-https"
    allowed_methods        = ["GET", "HEAD", "OPTIONS"]
    cached_methods         = ["GET", "HEAD"]
    compress               = true

    forwarded_values {
      query_string = false
      cookies {
        forward = "none"
      }
    }

    cache_policy_id         = "41387307-740e-45b4-b56c-f1b13554c009" # Managed-CachingOptimized
    response_headers_policy_id = aws_cloudfront_response_headers_policy.main.id
  }

  price_class = "PriceClass_100"

  aliases = [var.cloudfront_domain_name]

  viewer_certificate {
    acm_certificate_arn = var.acm_certificate_arn
    ssl_support_method  = "sni-only"
  }

  restrictions {
    geo_restriction {
      restriction_type = "none"
    }
  }
}

resource "aws_cloudfront_response_headers_policy" "main" {
  name = "${var.eks_cluster_name}-headers-${var.name}"

  security_headers_config {
    frame_options {
      frame_option = "DENY"
    }
    x_content_type_options {
      x_content_type_options = "true"
    }
  }

  cache_behavior {
    header {
      action = "remove"
      name   = "Via"
    }
  }
}
```

## `modules/app/outputs.tf`

```hcl
output "eks_cluster_endpoint" {
  value = aws_eks_cluster.cluster.endpoint
}

output "eks_cluster_arn" {
  value = aws_eks_cluster.cluster.arn
}

output "s3_bucket_name" {
  value = aws_s3_bucket.assets.id
}

output "s3_bucket_arn" {
  value = aws_s3_bucket.assets.arn
}

output "rds_endpoint" {
  value = aws_db_instance.database.endpoint
}

output "rds_address" {
  value = aws_db_instance.database.address
}

output "rds_port" {
  value = aws_db_instance.database.port
}

output "alb_dns_name" {
  value = aws_lb.main.dns_name
}

output "cloudfront_domain_name" {
  value = var.use_cloudfront ? aws_cloudfront_distribution.main[0].domain_name : null
}

output "cloudfront_distribution_id" {
  value = var.use_cloudfront ? aws_cloudfront_distribution.main[0].id : null
}

output "iam_service_user" {
  value = var.iam_oidc_provider_arn == "" ? aws_iam_user.service[0].name : null
}

output "iam_service_role_arn" {
  value = var.iam_oidc_provider_arn != "" ? aws_iam_role.service_oidc[0].arn : null
}
```

## Root: `terraform.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.region

  default_tags {
    tags = {
      ManagedBy = "terraform"
      Project   = "app"
    }
  }
}
```

## Root: `variables.tf`

```hcl
variable "region" {
  description = "AWS region"
  type        = string
}

variable "vpc_id" {
  description = "VPC ID"
  type        = string
}

variable "subnet_ids" {
  description = "Private subnet IDs"
  type        = list(string)
}

variable "environments" {
  description = "Map of environment configs to deploy"
  type = map(object({
    name                   = string
    region                 = string
    vpc_id                 = string
    subnet_ids             = list(string)
    eks_cluster_name       = string
    eks_instance_type      = string
    eks_desired_nodes      = number
    s3_bucket_name         = string
    s3_replication_enabled = bool
    s3_replication_target  = string
    rds_instance_class     = string
    rds_multi_az           = bool
    rds_encrypted          = bool
    iam_oidc_provider_arn  = string
    use_cloudfront         = bool
    acm_certificate_arn    = string
    cloudfront_domain_name = string
    db_password            = string
  }))
}
```

## Root: `main.tf`

```hcl
module "app" {
  source = "./modules/app"

  for_each = var.environments

  name                    = each.value.name
  region                  = each.value.region
  vpc_id                  = each.value.vpc_id
  subnet_ids              = each.value.subnet_ids
  eks_cluster_name        = each.value.eks_cluster_name
  eks_instance_type       = each.value.eks_instance_type
  eks_desired_nodes       = each.value.eks_desired_nodes
  s3_bucket_name          = each.value.s3_bucket_name
  s3_replication_enabled  = each.value.s3_replication_enabled
  s3_replication_target   = each.value.s3_replication_target
  rds_instance_class      = each.value.rds_instance_class
  rds_multi_az            = each.value.rds_multi_az
  rds_encrypted           = each.value.rds_encrypted
  iam_oidc_provider_arn   = each.value.iam_oidc_provider_arn
  use_cloudfront          = each.value.use_cloudfront
  acm_certificate_arn     = each.value.acm_certificate_arn
  cloudfront_domain_name  = each.value.cloudfront_domain_name
  db_password             = each.value.db_password
}
```

## Root: `outputs.tf`

```hcl
output "environments" {
  description = "Per-environment outputs"
  for_each     = module.app
  value = {
    eks_cluster_endpoint  = each.value.eks_cluster_endpoint
    eks_cluster_arn       = each.value.eks_cluster_arn
    s3_bucket_name        = each.value.s3_bucket_name
    rds_endpoint          = each.value.rds_endpoint
    alb_dns_name          = each.value.alb_dns_name
    cloudfront_domain     = each.value.cloudfront_domain_name
    iam_service_role_arn  = each.value.iam_service_role_arn
    iam_service_user      = each.value.iam_service_user
  }
}
```

## Root: `moved.tf`

This is the critical file that guarantees **zero-diff** state transitions. Every resource that previously lived under `module.dev.*` or `module.prod.*` is mapped to its new `module.app["dev"].*` / `module.app["prod"].*` address.

```hcl
# =============================================================================
# STATE MOVES — module.dev → module.app["dev"]
# =============================================================================

# EKS
moved {
  from = module.dev.aws_eks_cluster.cluster
  to   = module.app["dev"].aws_eks_cluster.cluster
}

moved {
  from = module.dev.aws_eks_node_group.workers
  to   = module.app["dev"].aws_eks_node_group.workers
}

moved {
  from = module.dev.aws_iam_role.eks_cluster
  to   = module.app["dev"].aws_iam_role.eks_cluster
}

moved {
  from = module.dev.aws_iam_role_policy_attachment.eks_cluster
  to   = module.app["dev"].aws_iam_role_policy_attachment.eks_cluster
}

moved {
  from = module.dev.aws_iam_role.eks_node
  to   = module.app["dev"].aws_iam_role.eks_node
}

moved {
  from = module.dev.aws_iam_role_policy_attachment.eks_node
  to   = module.app["dev"].aws_iam_role_policy_attachment.eks_node
}

moved {
  from = module.dev.aws_iam_role_policy_attachment.eks_node_cni
  to   = module.app["dev"].aws_iam_role_policy_attachment.eks_node_cni
}

# S3
moved {
  from = module.dev.aws_s3_bucket.assets
  to   = module.app["dev"].aws_s3_bucket.assets
}

moved {
  from = module.dev.aws_s3_bucket_versioning.assets
  to   = module.app["dev"].aws_s3_bucket_versioning.assets
}

moved {
  from = module.dev.aws_s3_bucket_server_side_encryption_configuration.assets
  to   = module.app["dev"].aws_s3_bucket_server_side_encryption_configuration.assets
}

moved {
  from = module.dev.aws_s3_bucket_public_access_block.assets
  to   = module.app["dev"].aws_s3_bucket_public_access_block.assets
}

# RDS
moved {
  from = module.dev.aws_db_subnet_group.main
  to   = module.app["dev"].aws_db_subnet_group.main
}

moved {
  from = module.dev.aws_security_group.rds
  to   = module.app["dev"].aws_security_group.rds
}

moved {
  from = module.dev.aws_db_instance.database
  to   = module.app["dev"].aws_db_instance.database
}

# IAM
moved {
  from = module.dev.aws_iam_user.service
  to   = module.app["dev"].aws_iam_user.service
}

moved {
  from = module.dev.aws_iam_access_key.service
  to   = module.app["dev"].aws_iam_access_key.service
}

moved {
  from = module.dev.aws_iam_policy.service
  to   = module.app["dev"].aws_iam_policy.service
}

moved {
  from = module.dev.aws_iam_user_policy_attachment.service
  to   = module.app["dev"].aws_iam_user_policy_attachment.service
}

# HTTPS
moved {
  from = module.dev.aws_security_group.alb
  to   = module.app["dev"].aws_security_group.alb
}

moved {
  from = module.dev.aws_lb.main
  to   = module.app["dev"].aws_lb.main
}

moved {
  from = module.dev.aws_lb_listener.https
  to   = module.app["dev"].aws_lb_listener.https
}


# =============================================================================
# STATE MOVES — module.prod → module.app["prod"]
# =============================================================================

# EKS
moved {
  from = module.prod.aws_eks_cluster.cluster
  to   = module.app["prod"].aws_eks_cluster.cluster
}

moved {
  from = module.prod.aws_eks_node_group.workers
  to   = module.app["prod"].aws_eks_node_group.workers
}

moved {
  from = module.prod.aws_iam_role.eks_cluster
  to   = module.app["prod"].aws_iam_role.eks_cluster
